--
-- Safe to run repeatedly: every row has a deterministic id and is upserted,
-- so a second run updates content in place and creates no duplicates.
--
-- Seeds CONTENT ONLY. No users, no progress, no assessment attempts - those
-- are created by people using the system.
--
-- Source: the training documents transcribed into src/data/. Where a document
-- refers to information it does not supply (product specifications, package
-- prices, flavours), the row is seeded with a null value so the UI shows
-- "Admin content required" instead of an invented figure.
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- PART 14 OF 23: Assessments, questions and choices
--
-- Run the parts in filename order. Each is idempotent on its own, so a part
-- can be re-run safely; running them out of order will fail on a foreign key.
-- ---------------------------------------------------------------------------

begin;

-- ---------------------------------------------------------------------------
-- Assessments, questions and choices
-- ---------------------------------------------------------------------------

on conflict (id) do update set
  slug = excluded.slug,
  title = excluded.title,
  description = excluded.description,
  module_id = excluded.module_id,
  passing_score = excluded.passing_score,
  time_limit_minutes = excluded.time_limit_minutes,
  attempts_allowed = excluded.attempts_allowed,
  status = excluded.status,
  published_at = excluded.published_at
;

on conflict (id) do update set
  assessment_id = excluded.assessment_id,
  type = excluded.type,
  prompt = excluded.prompt,
  explanation = excluded.explanation,
  points = excluded.points,
  sort_order = excluded.sort_order
;

on conflict (id) do update set
  question_id = excluded.question_id,
  text = excluded.text,
  is_correct = excluded.is_correct,
  sort_order = excluded.sort_order
;

commit;
